#!/usr/bin/env python3
"""Writes the plugin's translation table from the "kobo" section of i18n/*.json."""

import json
import sys
from pathlib import Path

root = Path(__file__).resolve().parent.parent
output = Path(sys.argv[1])


def c_string(text: str) -> str:
    return json.dumps(text, ensure_ascii=False)


languages = ["en"] + sorted(p.stem for p in (root / "i18n").glob("*.json") if p.stem != "en")
tables = {lang: json.loads((root / "i18n" / f"{lang}.json").read_text("utf-8"))["kobo"] for lang in languages}
keys = list(tables["en"])

lines = [
    "// Generated by scripts/gen-kobo-strings.py from i18n/*.json; do not edit.",
    f"constexpr int kLanguageCount = {len(languages)};",
    f"constexpr int kKeyCount = {len(keys)};",
    "const char *const kLanguages[kLanguageCount] = {" + ", ".join(c_string(l) for l in languages) + "};",
    "const char *const kKeys[kKeyCount] = {" + ", ".join(c_string(k) for k in keys) + "};",
    "const char *const kStrings[kLanguageCount][kKeyCount] = {",
]
for lang in languages:
    values = (c_string(tables[lang].get(key, tables["en"][key])) for key in keys)
    lines.append("    {" + ", ".join(values) + "},")
lines.append("};")

output.parent.mkdir(parents=True, exist_ok=True)
output.write_text("\n".join(lines) + "\n", "utf-8")
